const topics=[];function add(id,name,pages,gen){topics.push({id,name,pages,gen})}
function question(prompt,answer,wrong,steps,hint,visual=''){const choices=[{text:String(answer),correct:true,mistake:''}];for(const v of wrong){const text=String(Array.isArray(v)?v[0]:v);if(!choices.some(x=>x.text===text))choices.push({text,correct:false,mistake:Array.isArray(v)?v[1]:'Check which operation is needed and carry it through each step.'});if(choices.length===4)break}if(choices.length!==4)throw Error('Need four distinct choices: '+prompt);return {prompt,answer:String(answer),choices,steps,hint,visual}}
function numeric(prompt,answer,wrong,steps,hint,visual='',format=num){const vals=[...wrong,answer+1,answer-1,answer+2,answer-2,answer+3,answer-3];const seen=new Set([format(answer)]), ds=[];for(const v of vals){if(Number.isFinite(v)&&!seen.has(format(v))){seen.add(format(v));ds.push([format(v),'Recheck the operation and any signs, units, or parentheses.']);if(ds.length===3)break}}const q=question(prompt,format(answer),ds,steps,hint,visual);q.model={value:answer,options:[answer,...vals.filter(v=>Number.isFinite(v)&&format(v)!==format(answer))]};return q}
function graph(m=1,b=0,opts={}){const x=v=>180+v*22,y=v=>180-v*22;let s='';for(let i=-6;i<=6;i++){s+=`<path fill="none" d="M${x(i)} 48V312 M48 ${y(i)}H312" stroke="#dce2ee"/>`;if(i!==0&&i%2===0)s+=`<text x="${x(i)}" y="196" text-anchor="middle">${i}</text><text x="169" y="${y(i)+4}" text-anchor="end">${i}</text>`}let fill='';if(opts.shade){const pts=[[-6,-6],[6,-6],[6,6],[-6,6]];let out=[];for(let i=0;i<4;i++){const a=pts[i],c=pts[(i+1)%4],f=p=>opts.shade==='above'?p[1]-m*p[0]-b:m*p[0]+b-p[1],fa=f(a),fc=f(c);if(fa>=0)out.push(a);if((fa>=0)!==(fc>=0)){const t=fa/(fa-fc);out.push([a[0]+t*(c[0]-a[0]),a[1]+t*(c[1]-a[1])])}}fill=`<polygon points="${out.map(p=>`${x(p[0])},${y(p[1])}`).join(' ')}" fill="#cbd7ff"/>`}
return `<svg viewBox="0 0 360 350" role="img" aria-label="${opts.label||'Coordinate plane with the line y = '+lin(m,b)}"><defs><clipPath id="plot"><rect x="48" y="48" width="264" height="264"/></clipPath></defs><g font-family="Arial" font-size="12" fill="#54617b">${fill}${s}<path fill="none" d="M48 180H312 M180 48V312" stroke="#061746" stroke-width="2"/><text x="322" y="185">x</text><text x="183" y="38">y</text><text x="170" y="196">0</text><g clip-path="url(#plot)">${opts.line===false?'':`<path fill="none" d="M${x(-6)} ${y(-6*m+b)}L${x(6)} ${y(6*m+b)}" stroke="#cb1022" stroke-width="3" ${opts.dashed?'stroke-dasharray="7 5"':''}/>`}${(opts.points||[]).map(p=>`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="5" fill="#061746"/><text x="${x(p[0])+9}" y="${y(p[1])-9}">${p[2]||''}</text>`).join('')}${opts.extra||''}</g></g></svg>`}
function numberline(points){return `<svg viewBox="0 0 440 115" role="img" aria-label="Number line from negative five to five. Points: ${points.map(p=>p[1]+' at '+p[0]).join(', ')}"><path fill="none" d="M20 65H420" stroke="#061746" stroke-width="2"/>${Array.from({length:11},(_,i)=>`<path fill="none" d="M${20+i*40} 59v12" stroke="#061746"/><text x="${20+i*40}" y="95" text-anchor="middle" font-size="14">${i-5}</text>`).join('')}${points.map(p=>`<circle cx="${220+p[0]*40}" cy="65" r="5" fill="#cb1022"/><text x="${220+p[0]*40}" y="45" text-anchor="middle" font-size="16" fill="#061746">${p[1]}</text>`).join('')}</svg>`}
add('signed','Signed numbers & order of operations',['Screenshot',39,40],L=>{let a=rand(-12,12),b=rand(2,9),c=rand(2,6);if(L===1)return numeric(`What is ${a} − (−${b})?`,a+b,[a-b,-a-b,-a+b],[`Subtracting a negative is adding: ${a} − (−${b}) = ${a} + ${b}.`,`The result is ${a+b}.`],'Subtracting a negative changes the operation to addition.');if(L===2)return numeric(`What is ${a} − (−${b}) + ${c}?`,a+b+c,[a-b+c,a+b-c,-a-b+c],[`Rewrite as ${a} + ${b} + ${c}.`,`Add from left to right to get ${a+b+c}.`],'First rewrite the subtraction of a negative.');return numeric(`Evaluate ${L>=4?c+' × ':''}[${a} − (−${b})] ${L===5?'− '+c+'²':'+ '+c+'²'}.`,(L>=4?c:1)*(a+b)+(L===5?-1:1)*c*c,[(a-b)*c+c*c,(a+b+c)**2,(a+b)*c-c],[`Inside the brackets: ${a} − (−${b}) = ${a+b}.`,`The square is ${c}² = ${c*c}.`,`${L>=4?'Multiply the bracket by '+c+', then ':''}${L===5?'subtract':'add'} the square: ${(L>=4?c:1)*(a+b)+(L===5?-1:1)*c*c}.`],'Evaluate brackets and exponents before multiplication and addition.')});
add('fractions','Fractions & mixed numbers',[32,39,40],L=>{const d=L===1?pick([2,4]):pick([3,4,5,6]),e=L<=2?d:pick([2,3,4,5]),a=rand(1,d-1),b=rand(1,e-1),w=L>=2?rand(2,5):0,z=L>=3?rand(1,2):0,sub=L>=4;const n1=w*d+a,n2=z*e+b,n=n1*e+(sub?-1:1)*n2*d,den=d*e;return question(`Compute ${w?w+' ':''}${a}/${d} ${sub?'−':'+'} ${z?z+' ':''}${b}/${e}. Give your answer as a simplified fraction or integer.`,frac(n,den),[[frac(n1+(sub?-n2:n2),d+e),'Use a common denominator; do not add the denominators.'],frac(n+den,den),frac(n-den,den),frac(n1*e+n2*d,den)], [`${w?'Convert mixed numbers to improper fractions: ':''}${frac(n1,d)} and ${frac(n2,e)}.`,`Use denominator ${den}: ${n1*e}/${den} ${sub?'−':'+'} ${n2*d}/${den}.`,`Combine numerators and simplify: ${frac(n,den)}.`],'Convert any mixed numbers first, then use a common denominator.')});
add('proportion','Proportions & unit prices',['Screenshot',24,43],L=>{const unit=rand(2,8),n=rand(2,5),k=rand(6,12);if(L<=2)return numeric(`${n} notebooks cost $${n*unit}. At the same rate, what do ${k} notebooks cost?`,k*unit,[n*unit+k,unit,k*n*unit],[`One notebook costs $${n*unit} ÷ ${n} = $${unit}.`,`${k} notebooks cost ${k} × $${unit} = $${k*unit}.`],'Find the cost of one notebook.', '',v=>'$'+num(v));const factor=rand(2,5),base=rand(2,6);return numeric(`A recipe uses ${base} cups of flour for ${n*base} cookies. You need ${n*base*factor} cookies${L>=4?', but already have '+base+' cups of flour':''}. How many ${L>=4?'additional ':''}cups of flour do you need?`,base*factor-(L>=4?base:0),[base+factor,base*factor+base,n*factor],[`The batch multiplier is ${n*base*factor} ÷ ${n*base} = ${factor}.`,`Total flour needed: ${base} × ${factor} = ${base*factor} cups.`,L>=4?`Subtract the ${base} cups you already have: ${base*(factor-1)} cups.`:`You need ${base*factor} cups.`],'Find how many times larger the new batch is.')});
add('ratio','Sharing a total in a ratio',[19,20],L=>{const a=rand(1,L+1),b=rand(a+1,a+4),k=rand(3,12),total=(a+b)*k,diff=(b-a)*k;return numeric(L<=3?`Ava and Ben share ${total} tickets in a ratio of ${a}:${b}. How many tickets does Ben get?`:`Ava and Ben share tickets in a ratio of ${a}:${b}. Ben gets ${diff} more tickets than Ava. How many tickets do they have altogether?`,L<=3?b*k:total,[a*k,(a+b)*k,b*diff,total-k],[L<=3?`There are ${a+b} ratio parts, so each part is ${total} ÷ ${a+b} = ${k}.`:`The difference is ${b-a} parts, so each part is ${diff} ÷ ${b-a} = ${k}.`,L<=3?`Ben gets ${b} × ${k} = ${b*k} tickets.`:`The total is (${a} + ${b}) × ${k} = ${total} tickets.`],'Use the number of ratio parts, not just one of the ratio numbers.')});
add('percent','Percent discounts',['Screenshot'],L=>{const price=rand(3,15)*10,percent=pick([10,20,25,50]),sale=price*(1-percent/100),extra=pick([10,20,50]);if(L<=2)return numeric(`A $${price} jacket is ${percent}% off. What is the sale price?`,sale,[price*percent/100,price+price*percent/100,price-percent],[`Discount: $${price} × ${percent}/100 = ${money(price*percent/100)}.`,`Sale price: $${price} − ${money(price*percent/100)} = ${money(sale)}.`],'Subtract the discount from the original price.','',money);if(L===3)return numeric(`A jacket costs ${money(sale)} after a ${percent}% discount. What was its original price?`,price,[sale*(1+percent/100),sale+percent,sale*100/percent],[`The sale price is ${100-percent}% of the original.`,`Original price = ${money(sale)} ÷ ${num(1-percent/100)} = ${money(price)}.`],'The sale price is the remaining percentage of the original.','',money);return numeric(`A $${price} jacket is discounted ${percent}%, then the reduced price is discounted another ${extra}%. What is the final price?`,sale*(1-extra/100),[price*(1-(percent+extra)/100),sale,sale*(1+extra/100)],[`After the first discount: ${money(sale)}.`,`Apply the second discount to that reduced price: ${money(sale)} × ${num(1-extra/100)} = ${money(sale*(1-extra/100))}.`],'Successive discounts apply to successive prices.','',money)});
add('tax','Tax, tips & reverse percentages',[27,28],L=>{const base=rand(3,12)*10,p=pick([10,15,20,25]),total=base*(1+p/100);if(L<=2)return numeric(`A meal costs $${base} before tip. You leave a ${p}% tip. ${L===1?'How much is the tip?':'What is the total including tip?'}`,L===1?base*p/100:total,[base*p/100,base+p,total,base],[`Tip = $${base} × ${p}/100 = ${money(base*p/100)}.`,L===1?`The tip is ${money(base*p/100)}.`:`Total = $${base} + ${money(base*p/100)} = ${money(total)}.`],'Find the percentage of the original bill.','',money);if(L===3)return numeric(`The total including a ${p}% tip is ${money(total)}. What was the bill before tip?`,base,[total-total*p/100,total-p,total/(p/100)],[`The total is ${100+p}% of the original bill.`,`Divide ${money(total)} by ${num(1+p/100)} to get ${money(base)}.`],'Write total = original × (1 + tip rate).','',money);const tax=10;return numeric(`A meal costs $${base} before tax. Add ${tax}% tax, then a ${p}% tip calculated on the original bill. What is the total?`,base*(1+(tax+p)/100),[base*(1+tax/100)*(1+p/100),base*(tax+p)/100,total],[`Tax: ${money(base*tax/100)}. Tip on the original bill: ${money(base*p/100)}.`,`Add both to $${base}: ${money(base*(1+(tax+p)/100))}.`],'Both percentages are explicitly based on the original bill.','',money)});
add('powers','Negative exponents & exponent laws',['Screenshot',40],L=>{const a=pick([2,3,4,5]),n=rand(2,4);if(L<=2)return question(`What is ${a}<sup>−${n}</sup>?`,frac(1,a**n),[-(a**n),frac(-1,a**n),frac(1,a*n),a**n],[`A negative exponent means a reciprocal: ${a}<sup>−${n}</sup> = 1/${a}<sup>${n}</sup>.`,`Since ${a}<sup>${n}</sup> = ${a**n}, the answer is ${frac(1,a**n)}.`],'The negative sign in the exponent does not make the result negative.');const m=rand(2,5),p=rand(2,4),exp=L===3?n+m:L===4?n*p:(n+m)*p;return question(`Which expression is equivalent to ${L===3?`x<sup>${n}</sup> · x<sup>${m}</sup>`:L===4?`(x<sup>${n}</sup>)<sup>${p}</sup>`:`(x<sup>${n}</sup> · x<sup>${m}</sup>)<sup>${p}</sup>`}?`, `x<sup>${exp}</sup>`,[`x<sup>${exp+1}</sup>`,`x<sup>${n+m+p}</sup>`,`x<sup>${n*m*p}</sup>`,`x<sup>${exp-1}</sup>`],[`When multiplying like bases, add their exponents.`,`When raising a power to a power, multiply the exponents.`,`The final exponent is ${exp}.`],'Use the product rule inside parentheses before the power rule.')});
add('rational','Rational exponents & radicals',[35],L=>{const base=rand(2,9),d=L<=2?2:pick([2,3,4]),n=L<=1?1:rand(1,d+1),forward=L%2===1,rootName=v=>({2:'square root',3:'cube root',4:'fourth root',5:'fifth root',6:'sixth root'}[v]||v+'th root');const radical=(den,pow)=>`(${rootName(den)} of ${base})<sup>${pow}</sup>`;const ans=forward?radical(d,n):`${base}<sup>${n}/${d}</sup>`;return question(forward?`Write ${base}<sup>${n}/${d}</sup> in radical form.`:`Write ${radical(d,n)} using a rational exponent.`,ans,forward?[radical(n+1,d),radical(d,n+1),`${base}<sup>${n+d}</sup>`,radical(d,n+2)]:[`${base}<sup>${d}/${n+1}</sup>`,`${base}<sup>${n+d}</sup>`,`${base}<sup>−${n}/${d}</sup>`],[`In a rational exponent, the denominator gives the root and the numerator gives the power.`,`${base}<sup>${n}/${d}</sup> = ${radical(d,n)}.`],'Denominator = root; numerator = power.')});
add('simplify','Distribute & combine like terms',['Screenshot',40],L=>{const a=rand(2,6),b=rand(2,8),c=rand(2,5),d=L>=3?rand(1,5):0,sub=L>=4,coef=a+(sub?-c:c),constant=a*b-d;const answer=lin(coef,constant);return question(`Simplify ${a}(x + ${b}) ${sub?'−':'+'} ${c}x${d?' − '+d:''}.`,answer,[lin(coef,b-d),lin(a+c,a*b+d),lin(coef+1,constant),lin(coef,constant+1)],[`Distribute ${a} to both terms: ${a}x + ${a*b}.`,`Combine x terms: ${a}x ${sub?'−':'+'} ${c}x = ${coef}x.`,`Combine constants: ${a*b}${d?' − '+d:''} = ${constant}.`,`Result: ${answer}.`],'Distribute to every term inside the parentheses.')});
add('linear','Solve linear equations',['Screenshot',39],L=>{const x=rand(-3,8),a=rand(2,6),b=rand(2,10),c=L>=4?rand(1,a-1):0;if(L<=2)return numeric(`Solve: ${a}x − ${b} = ${a*x-b}.`,x,[(a*x-b)/a,x-b,a*x],[`Add ${b} to both sides: ${a}x = ${a*x}.`,`Divide both sides by ${a}: x = ${x}.`],'Undo addition or subtraction before multiplication.','',v=>'x = '+num(v));if(L===3)return numeric(`Solve: ${a}(x + ${b}) = ${a*(x+b)}.`,x,[x+b,(a*(x+b)-b)/a,-x],[`Divide both sides by ${a}: x + ${b} = ${x+b}.`,`Subtract ${b}: x = ${x}.`],'You can divide both sides by the factor outside the parentheses.','',v=>'x = '+num(v));return numeric(`Solve: ${a}(x + ${b}) = ${c}x + ${a*(x+b)-c*x}.`,x,[x+b,-x,x-1],[`Distribute: ${a}x + ${a*b} = ${c}x + ${a*(x+b)-c*x}.`,`Subtract ${c}x and ${a*b}: ${a-c}x = ${(a-c)*x}.`,`Divide by ${a-c}: x = ${x}.`],'Move variable terms to one side and constants to the other.','',v=>'x = '+num(v))});
add('substitute','Substitution & linked equations',[4,5],L=>{const a=rand(2,5),b=rand(1,5),x=rand(1,6),y=rand(2,9),total=a*x+b*y;if(L===1)return numeric(`If x = ${x}, what is ${a}x + ${b}?`,a*x+b,[a+x+b,a*x-b,a*(x+b)],[`Replace x with ${x}: ${a}(${x}) + ${b}.`,`Multiply, then add: ${a*x+b}.`],'Replace the variable with its given value.');if(L===2)return numeric(`If x = ${x} and ${a}x + ${b}y = ${total}, what is y?`,y,[(total-a*x),total/b,x],[`Substitute: ${a*x} + ${b}y = ${total}.`,`Subtract ${a*x}: ${b}y = ${b*y}.`,`Divide by ${b}: y = ${y}.`],'Use the known variable to solve for the other.');return numeric(`If ${a}x − ${b} = ${a*x-b} and ${b}x + ${a}y = ${b*x+a*y}, what is ${L>=4?'xy':'y'}?`,L>=4?x*y:y,[x,y,x+y,x*y+1],[`First equation: ${a}x = ${a*x}, so x = ${x}.`,`Substitute into the second: ${b*x} + ${a}y = ${b*x+a*y}, so y = ${y}.`,L>=4?`Multiply: xy = ${x} × ${y} = ${x*y}.`:`Thus y = ${y}.`],'Solve the first equation, then substitute into the second.')});
add('tablelinear','Linear equations from tables',[6,7],L=>{const m=pick(L>=3?[-3,-2,2,3]:[1,2,3]),b=rand(-4,5),xs=L>=4?[-2,1,4]:[-1,0,1];const ans='y = '+lin(m,b);return question('Which equation matches this table?',ans,['y = '+lin(-m,b),'y = '+lin(m,b+2),'y = '+lin(m+1,b)],[`Slope = change in y ÷ change in x = ${m}.`,`Using x = ${xs[0]}, solve ${m*xs[0]+b} = ${m}(${xs[0]}) + b to get b = ${b}.`,`The equation is ${ans}.`],'Find the slope from two rows, then find the y-intercept.',table(['x','y'],xs.map(x=>[x,m*x+b])))});
