add('slope','Slope & perpendicular lines',[11],L=>{const m=pick([2,3,4,-2,-3]),b=rand(-5,5);if(L===1)return numeric(`What is the slope of y = ${lin(m,b)}?`,m,[b,-m,m+1],[`In y = mx + b, the coefficient of x is the slope.`,`Here the slope is ${m}.`],'Look at the coefficient of x.');const answer=frac(-1,m);return question(L<=3?`What is the slope of a line perpendicular to y = ${lin(m,b)}?`:`A line passes through (0, ${b}) and (${L}, ${m*L+b}). What is the slope of a perpendicular line?`,answer,[frac(1,m),String(-m),String(m)],L<=3?[`The original slope is ${m}.`,`Perpendicular slopes have product −1. Take the negative reciprocal: ${answer}.`]:[`Original slope = (${m*L+b} − (${b})) / (${L} − 0) = ${m}.`,`Its negative reciprocal is ${answer}.`],'Perpendicular slopes are negative reciprocals.')});
