add('rates','Rates, distance & time',[8,9,43],L=>{const r=rand(3,8)*10,t=rand(2,5),d=r*t;if(L===1)return numeric(`A cyclist travels at ${r} miles per hour for ${t} hours. How far does the cyclist travel?`,d,[r+t,r/t,d+r],[`Distance = rate × time.`,`${r} × ${t} = ${d} miles.`],'Use distance = rate × time.');if(L===2)return numeric(`A car travels ${d} miles at ${r} miles per hour. How many hours does the trip take?`,t,[d*r,d-r,r/t],[`Time = distance ÷ rate.`,`${d} ÷ ${r} = ${t} hours.`],'Rearrange distance = rate × time to find time.');const stop=rand(1,3),target=d+stop*r;return numeric(`A car must travel ${target} miles at ${r} miles per hour. It has already driven ${d} miles${L>=4?' and will stop for 30 minutes':''}. How many more hours until arrival?`,stop+(L>=4?.5:0),[target/r,stop-.5,stop+1],[`Remaining distance = ${target} − ${d} = ${stop*r} miles.`,`Driving time = ${stop*r} ÷ ${r} = ${stop} hours.`,L>=4?`Add 30 minutes = 0.5 hour: ${stop+.5} hours.`:`The remaining time is ${stop} hours.`],'Find the remaining distance before dividing by the rate.')});
add('rateequation','Model rates & interpret equations',[9,37,39],L=>{const r=rand(3,15),b=L>=3?rand(5,20):0;if(L<=2)return question(`A printer produces ${r} pages per minute. Which equation gives the total pages p after t minutes?`,`p = ${r}t`,[`p = t/${r}`,`p = t + ${r}`,`t = ${r}p`],[`Total pages = pages per minute × minutes.`,`Therefore p = ${r}t.`],'Multiply the unit rate by elapsed time.');if(L===3)return question(`A student earns M = ${r}h + ${b} dollars for h hours of work. What does ${b} represent?`,'A fixed payment in addition to hourly pay',['The hourly pay rate','The number of hours worked','The total earned for every possible shift'],[`The term ${r}h changes with hours worked.`,`The constant ${b} is paid even when h = 0: it is a fixed payment.`],'Consider what remains when the number of hours is zero.');return question(`A student receives a $${b} fixed payment plus $${r} per hour. Which expression gives earnings after ${L===5?'h + 2':'h'} hours?`,L===5?`${r}(h + 2) + ${b}`:`${r}h + ${b}`,L===5?[`${r}h + 2 + ${b}`,`${r}(h + ${b}) + 2`,`${r}h + ${b}`]:[`${b}h + ${r}`,`${r}(h + ${b})`,`(${r} + ${b})h`,`${r}h − ${b}`],[`Multiply the hourly rate by all hours worked.`,`Then add the fixed payment once.`,L===5?`Earnings = ${r}(h + 2) + ${b}.`:`Earnings = ${r}h + ${b}.`],'A fixed payment is added once, not once per hour.')});
add('mean','Mean, median, mode & range',[2,3,'Screenshot'],L=>{const b=rand(3,15),d=rand(1,4),values=L<=2?[b,b+d,b+2*d,b+3*d]:[b,b+d,b+d,b+3*d,b+5*d],kind=pick(['mean','median','mode','range'].filter(k=>!(L<=2&&k==='mode'))),sorted=[...values].sort((a,b)=>a-b),sum=values.reduce((a,b)=>a+b,0),answer=kind==='mean'?sum/values.length:kind==='median'?(sorted[Math.floor((values.length-1)/2)]+sorted[Math.floor(values.length/2)])/2:kind==='mode'?b+d:sorted.at(-1)-sorted[0];return numeric(`What is the ${kind} of ${shuffle(values).join(', ')}?`,answer,[sum,b+d,sorted.at(-1),b,answer+1],[kind==='mean'?`Add the values: ${sum}. Divide by the ${values.length} values: ${num(answer)}.`:kind==='median'?`Order the values: ${sorted.join(', ')}. ${values.length%2?'Take the middle value.':'Average the two middle values.'} The median is ${num(answer)}.`:kind==='mode'?`${b+d} appears most often, so it is the mode.`:`Largest minus smallest: ${sorted.at(-1)} − ${sorted[0]} = ${answer}.`],kind==='mean'?'Mean = sum ÷ count.':kind==='median'?'Sort the list before finding the middle.':kind==='mode'?'Find the value that occurs most often.':'Range = largest − smallest.')});
add('timerange','Range of times',[2],L=>{const secs=[rand(20,50),rand(60,90),rand(100,140),rand(150,190)],fmt=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`,v=secs.at(-1)-secs[0];return numeric(`These race times are in minutes:seconds: ${shuffle(secs).map(fmt).join(', ')}. What is their range${L>=3?' in minutes:seconds':' in seconds'}?`,v,[secs.at(-1),secs[0],v+60,v-60],[`Convert the smallest and largest times to seconds: ${secs[0]} and ${secs.at(-1)}.`,`Range = ${secs.at(-1)} − ${secs[0]} = ${v} seconds${L>=3?' = '+fmt(v):''}.`],'One minute is 60 seconds, not 100.','',L>=3?fmt:num)});
add('missingmean','Missing values in an average',[10],L=>{const n=L<=2?3:5,mean=rand(70,85),known=Array.from({length:n-1},()=>mean+rand(-8,8)),sum=known.reduce((a,b)=>a+b,0),missing=n*mean-sum;if(L<=3)return numeric(`The average of ${n} test scores is ${mean}. The known scores are ${known.join(', ')}. What is the missing score?`,missing,[mean,sum/(n-1),n*mean,missing+mean],[`The required total is ${n} × ${mean} = ${n*mean}.`,`Known scores total ${sum}.`,`Missing score = ${n*mean} − ${sum} = ${missing}.`],'Find the required total, then subtract the known scores.');const newMean=mean+2,ans=(n+1)*newMean-n*mean;return numeric(`A student has an average of ${mean} on ${n} equally weighted tests. What score on the next test will raise the average to ${newMean}?`,ans,[newMean,mean+2,ans-mean],[`Current total = ${n} × ${mean} = ${n*mean}.`,`Required total after ${n+1} tests = ${n+1} × ${newMean} = ${(n+1)*newMean}.`,`Next score = ${(n+1)*newMean} − ${n*mean} = ${ans}.`],'The next test changes both the total and the number of tests.')});
add('numberline','Number lines & irrational numbers',[12,13],L=>{let value,expr;if(L<=2){value=pick([-3.5,-2.25,-.75,.5,1.25,2.5,3.75]);expr=num(value)}else if(L===3){const n=pick([2,3,5,7,10]);value=Math.sqrt(n);expr='√'+n}else if(L===4){const n=pick([2,3,5,7,10]);value=-Math.sqrt(n);expr='−√'+n}else{value=Math.PI/pick([1,2,3]);expr=Math.abs(value-Math.PI)<.001?'π':Math.abs(value-Math.PI/2)<.001?'π/2':'π/3'}const vals=shuffle([value,Math.max(-4.8,value-1.2),Math.min(4.8,value+1),-4.5]).sort((a,b)=>a-b);const points=vals.map((v,i)=>[v,'PQRS'[i]]),answer=points.find(p=>p[0]===value)[1];return question(`Which labeled point represents ${expr}?`,answer,points.filter(p=>p[1]!==answer).map(p=>p[1]),[`The value ${expr} is approximately ${num(value)}.`,`Locate ${value<0?'left':'right'} of zero, between ${Math.floor(value)} and ${Math.ceil(value)}.`,`That location is point ${answer}.`],'Estimate the value first, then compare its position with the ticks.',numberline(points))});
add('inequality','Linear inequalities & shaded graphs',[12,13,14,15,16],L=>{const m=pick([-1,1,2]),b=rand(-2,2),above=Math.random()<.5,strict=L>=3,op=above?(strict?'>':'≥'):(strict?'<':'≤');if(L<=2){const x=rand(1,4),a=rand(2,5),c=rand(1,5),v=a*x+c;return question(`Solve ${a}x + ${c} ≤ ${v}.`,`x ≤ ${x}`,[`x ≥ ${x}`,`x < ${x}`,`x ≤ ${v-c}`],[`Subtract ${c}: ${a}x ≤ ${v-c}.`,`Divide by positive ${a}, keeping the inequality direction: x ≤ ${x}.`],'Dividing by a positive number keeps the direction the same.')}return question('Which inequality matches the shaded graph?',`y ${op} ${lin(m,b)}`,[`y ${above?(strict?'<':'≤'):(strict?'>':'≥')} ${lin(m,b)}`,`y ${above?(strict?'≥':'>'):(strict?'≤':'<')} ${lin(m,b)}`,`y ${op} ${lin(-m,b+1)}`],[`The boundary line is y = ${lin(m,b)}.`,`The shading is ${above?'above':'below'} the line, so use ${above?'greater than':'less than'}.`,`The ${strict?'dashed':'solid'} boundary ${strict?'excludes':'includes'} the line: y ${op} ${lin(m,b)}.`],'Check boundary equation, shading direction, and whether the boundary is solid.',graph(m,b,{shade:above?'above':'below',dashed:strict,label:`Boundary through (0, ${b}) and (1, ${m+b}), ${strict?'dashed':'solid'}, shaded ${above?'above':'below'}.`}))});
add('systemineq','Systems of inequalities: solutions',[14,15,16],L=>{const b=rand(-2,1),c=b+pick([3,4,5]),x=0,y=b+1;const ans=`(${x}, ${y})`,wrong=[`(0, ${b-1})`,`(0, ${c+1})`,`(4, ${b+1})`];return question(`Which point satisfies both y ${L>=3?'>':'≥'} x ${sign(b)} and y ≤ −x ${sign(c)}?`,ans,wrong,[`For (${x}, ${y}), the first boundary value is ${x+b}; ${y} ${L>=3?'>':'≥'} ${x+b} is true.`,`The second boundary value is ${-x+c}; ${y} ≤ ${-x+c} is true.`,`The point must satisfy both inequalities.`],'Substitute each point into both inequalities; both must be true.',L>=4?graph(1,b,{shade:'above',dashed:L>=3,label:`First boundary y = x ${sign(b)}, shaded above; second boundary y = −x ${sign(c)} shown in navy. Test both inequalities.`,extra:`<path fill="none" d="M48 ${180-(-(-6)+c)*22}L312 ${180-(-6+c)*22}" stroke="#061746" stroke-width="3"/>`}):'')});
add('systems','Systems of equations',[4,5,17,18,41,42],L=>{const x=rand(1,6),y=rand(1,6),a=L<=2?1:rand(2,4),b=rand(1,3),c=1,d=-1,v=a*x+b*y,w=x-y;return question(`Solve the system: ${a}x + ${b}y = ${v} and x − y = ${w}. Give (x, y).`,`(${x}, ${y})`,[`(${x+1}, ${y})`,`(${x}, ${y+1})`,`(${x-1}, ${y-1})`],[`From x − y = ${w}, write x = y ${sign(w)}.`,`Substitute: ${a}(y ${sign(w)}) + ${b}y = ${v}.`,`So ${a+b}y = ${v-a*w}; y = ${y}.`,`Then x = ${y} ${sign(w)} = ${x}.`],'Solve one equation for x, then substitute into the other.')});
add('systemwords','Systems from word problems',[17,18,42],L=>{const a=rand(2,5),b=rand(6,9),x=rand(3,10),y=rand(3,10),n=x+y,revenue=a*x+b*y;if(L<=2)return question(`Student tickets cost $${a}; adult tickets cost $${b}. There are ${n} tickets sold for $${revenue}. Let s be student tickets and a be adult tickets. Which system models this?`,`s + a = ${n}; ${a}s + ${b}a = ${revenue}`,[`${a}s + ${b}a = ${n}; s + a = ${revenue}`,`s − a = ${n}; ${a}s + ${b}a = ${revenue}`,`s + a = ${n}; ${b}s + ${a}a = ${revenue}`],[`The ticket count gives s + a = ${n}.`,`The money collected gives ${a}s + ${b}a = ${revenue}.`],'Write one equation for the count and one for the cost.');return numeric(`Student tickets cost $${a}; adult tickets cost $${b}. A total of ${n} tickets brings in $${revenue}. How many adult tickets were sold?`,y,[x,n,y+1],[`Let s + a = ${n} and ${a}s + ${b}a = ${revenue}.`,`Substitute s = ${n} − a: ${a*n} + ${b-a}a = ${revenue}.`,`So a = (${revenue} − ${a*n}) ÷ ${b-a} = ${y}.`],'Use the total count to express one ticket type in terms of the other.')});
add('literal','Rearrange formulas',[21],L=>{const a=rand(2,7),b=rand(2,9);if(L<=2)return question(`Solve u = ${a}x − ${b} for x.`,`x = (u + ${b})/${a}`,[`x = (u − ${b})/${a}`,`x = ${a}(u + ${b})`,`x = u/${a} + ${b}`],[`Add ${b} to both sides: u + ${b} = ${a}x.`,`Divide by ${a}: x = (u + ${b})/${a}.`],'Undo subtraction, then divide by the coefficient.');if(L===3)return question(`Solve V = ${a}lwh for w. Assume l and h are nonzero.`,`w = V/(${a}lh)`,[`w = V − ${a}lh`,`w = ${a}Vh/l`,`w = ${a}Vlh`],[`Divide both sides by ${a}lh.`,`This leaves w = V/(${a}lh).`],'Divide by everything multiplied by w.');return question(`Solve A = ${a}πr² for the nonnegative radius r.`,`r = √(A/(${a}π))`,[`r = A/(${a}π)`,`r = √A/(${a}π)`,`r = A²/(${a}π)`],[`Divide by ${a}π: r² = A/(${a}π).`,`Take the nonnegative square root: r = √(A/(${a}π)).`],'Isolate the square of the radius before taking its square root.')});
add('angles','Angles: triangles, lines & parallels',[22,23],L=>{const a=rand(30,70),b=rand(30,60);if(L===1)return numeric(`A triangle has angles ${a}° and ${b}°. What is its third angle?`,180-a-b,[a+b,180-a,90-a],[`Triangle angles add to 180°.`,`Missing angle = 180 − ${a} − ${b} = ${180-a-b}°.`],'The interior angles of a triangle total 180°.');if(L===2)return numeric(`Two angles form a straight line. One is ${a}°. What is the other angle?`,180-a,[a,90-a,360-a],[`A straight angle is 180°.`,`The other angle is 180 − ${a} = ${180-a}°.`],'Adjacent angles on a straight line sum to 180°.');const coeff=rand(2,5),x=rand(10,20),offset=rand(1,9),ang=coeff*x+offset;return numeric(L===3?`Parallel lines are cut by a transversal. Corresponding angles measure (${coeff}x + ${offset})° and ${ang}°. Find x.`:L===4?`Two same-side interior angles between parallel lines are (${coeff}x + ${offset})° and ${180-ang}°. Find x.`:`A triangle has angles (${coeff}x + ${offset})°, ${b}°, and ${180-ang-b}°. Find x.`,x,[ang/coeff,(ang+offset)/coeff,ang-offset],[L===3?`Corresponding angles are equal: ${coeff}x + ${offset} = ${ang}.`:L===4?`Same-side interior angles add to 180°: ${coeff}x + ${offset} + ${180-ang} = 180.`:`Triangle angles sum to 180°: ${coeff}x + ${offset} + ${b} + ${180-ang-b} = 180.`,`This gives ${coeff}x = ${coeff*x}; divide by ${coeff} to get x = ${x}.`],'Decide whether the angles are equal or add to 180°.')});
add('twoway','Two-way tables & conditional probability',[25,26,40],L=>{const a=rand(4,12),b=rand(4,12),c=rand(4,12),d=rand(4,12),all=a+b+c+d,conditional=L>=3,den=conditional?a+b:all;return question(`A student is chosen at random${conditional?' from students in Art Club':''}. What is the probability that the student ${conditional?'prefers science':'is in Art Club and prefers science'}?`,frac(b,den),[frac(b,all-b),frac(a,den),frac(b,a+c),frac(b,all),frac(a+b,all),frac(b,den+1),frac(b,den+2),frac(b,den+3)], [`The favorable count is ${b}.`,conditional?`Restrict the sample space to Art Club: ${a} + ${b} = ${den}.`:`The full sample space is ${all} students.`,`Probability = favorable ÷ total = ${frac(b,den)}.`],'Use only the specified group as the denominator when the question says “from” that group.',table(['Club','Prefers math','Prefers science','Total'],[['Art',a,b,a+b],['Music',c,d,c+d],['Total',a+c,b+d,all]]))});
add('units','Unit conversions & comparisons',[29,30,39,41],L=>{if(L===1){const n=rand(2,8);return numeric(`How many grams are in ${n} kilograms? Use 1 kilogram = 1,000 grams.`,n*1000,[n*100,n/1000,n+1000],[`Multiply by 1,000 grams per kilogram: ${n} × 1,000 = ${n*1000}.`],'Convert a larger unit to a smaller unit by multiplying.')}if(L===2){const n=rand(3,9)*100,extra=rand(1,5)*100;return numeric(`Two files have sizes ${num(n/1000)} gigabytes and ${extra} megabytes. What is their total size in megabytes? Use 1 gigabyte = 1,000 megabytes.`,n+extra,[n/1000+extra,n+extra*1000,n-extra],[`Convert ${num(n/1000)} GB to ${n} MB.`,`Add ${extra} MB: ${n+extra} MB.`],'Convert both quantities to the same unit first.')}const m=rand(2,8),feet=rand(2,5),inches=rand(1,11);if(L===3)return numeric(`A ribbon is ${feet} feet ${inches} inches long. What is its length in inches? Use 1 foot = 12 inches.`,feet*12+inches,[feet+inches,feet*10+inches,feet*12-inches],[`Convert feet: ${feet} × 12 = ${feet*12} inches.`,`Add ${inches} inches: ${feet*12+inches} inches.`],'Convert feet to inches before adding.');return numeric(`A hiker climbs ${m*1000} meters from a trailhead at ${feet*100} meters. What is the summit elevation in kilometers? Use 1 kilometer = 1,000 meters.`,(m*1000+feet*100)/1000,[m-feet/10,m+feet,m*1000+feet*100],[`Summit elevation = ${m*1000} + ${feet*100} = ${m*1000+feet*100} meters.`,`Divide by 1,000: ${num(m+feet/10)} kilometers.`],'Add elevations in meters before converting to kilometers.')});
add('estimation','Estimate squares & roots',[31,12,13],L=>{const n=rand(L<=2?10:20,L<=2?30:60),delta=pick([.1,.2,.9]),x=n+delta;if(L<=3)return numeric(`Estimate ${num(x)}² by rounding ${num(x)} to the nearest whole number first.`,Math.round(x)**2,[2*Math.round(x),Math.round(x)**2+100,Math.round(x)**2-100],[`Round ${num(x)} to ${Math.round(x)}.`,`Square the rounded value: ${Math.round(x)} × ${Math.round(x)} = ${Math.round(x)**2}.`],'Round first, then square.');const b=rand(3,12),v=b*b+rand(1,2*b);return question(`Between which consecutive integers does √${v} lie?`,`${b} and ${b+1}`,[`${b-1} and ${b}`,`${b+1} and ${b+2}`,`${v-1} and ${v}`],[`${b}² = ${b*b} and ${b+1}² = ${(b+1)**2}.`,`${b*b} < ${v} < ${(b+1)**2}, so ${b} < √${v} < ${b+1}.`],'Compare the number under the root with nearby perfect squares.')});
add('probability','Probability & independent events',[33,'Screenshot'],L=>{if(L<=2){const r=rand(2,8),b=rand(3,9),g=L===2?rand(1,4):0;return question(`A bag contains ${r} red, ${b} blue${g?', and '+g+' green':''} marbles. What is the probability of choosing red?`,frac(r,r+b+g),[frac(r,b),frac(b,r+b+g),frac(r,r+b+g+1),frac(r,r+b+g+2),frac(r,r+b+g+3)],[`Favorable outcomes: ${r} red marbles.`,`Total outcomes: ${r} + ${b}${g?' + '+g:''} = ${r+b+g}.`,`Probability = ${frac(r,r+b+g)}.`],'Count all marbles for the denominator.')}const n=L===3?2:L===4?3:4,die=L===5,d=die?6:2;return question(`What is the probability of ${die?'rolling a 3 on each of '+n+' independent rolls of a fair six-sided die':'getting tails on each of '+n+' independent flips of a fair coin'}?`,frac(1,d**n),[frac(1,d*n),frac(n,d**n),frac(1,d**(n-1)),String(0),frac(1,d**(n+1))],[`Each outcome has probability 1/${d}.`,`Multiply probabilities for independent events: (1/${d})<sup>${n}</sup> = ${frac(1,d**n)}.`],'For independent events that must all happen, multiply probabilities.')});
// The sector, angle marker, and label all use the same clockwise sweep from the top radius.
function sectorDiagram(radius,angle){
 const center=160,R=110,at=(r,degrees)=>{const a=(degrees-90)*Math.PI/180;return [center+r*Math.cos(a),center+r*Math.sin(a)].map(n=>Math.round(n*1000)/1000)},end=at(R,angle),arcEnd=at(32,angle),label=at(60,angle/2),large=angle>180?1:0;
 return `<svg viewBox="0 0 320 320" role="img" aria-label="Circle radius ${radius} centimeters. The blue shaded sector has central angle ${angle} degrees." font-family="Arial" fill="#061746"><circle cx="160" cy="160" r="110" fill="white" stroke="#061746" stroke-width="2"/><path class="sector-region" d="M160 160 L160 50 A110 110 0 ${large} 1 ${end[0]} ${end[1]} Z" fill="#bfd0f6" stroke="#061746" stroke-width="2"/><path class="sector-angle-marker" d="M160 128 A32 32 0 ${large} 1 ${arcEnd[0]} ${arcEnd[1]}" fill="none" stroke="#061746" stroke-width="1.5"/><circle cx="160" cy="160" r="3" fill="#061746"/><text class="sector-radius-label" x="147" y="104" text-anchor="end" dominant-baseline="middle" font-size="17" paint-order="stroke" stroke="white" stroke-width="4" stroke-linejoin="round">${radius} cm</text><text class="sector-angle-label" x="${label[0]}" y="${label[1]}" text-anchor="middle" dominant-baseline="middle" font-size="17" paint-order="stroke" stroke="white" stroke-width="4" stroke-linejoin="round">${angle}°</text></svg>`;
}
add('sector','Circle sectors & shaded area',[34],L=>{const r=pick([2,4,6]),angle=pick(L<=2?[90,180]:[60,120,240,270]),answer=angle/360*r*r;return numeric(`A circle has radius ${r} cm. The shaded sector has central angle ${angle}°. What is its area? Leave π in the answer.`,answer,[r*r,angle/360*2*r,angle/180*r*r],[`Full circle area = πr² = ${r*r}π cm².`,`The sector is ${angle}/360 of the circle.`,`Sector area = (${angle}/360) × ${r*r}π = ${num(answer)}π cm².`],'Multiply the full circle area by the fraction of the full turn.',sectorDiagram(r,angle),v=>`${num(v)}π cm²`)});
add('volume','Volume, base area & dimensions',['Screenshot',40],L=>{const l=rand(2,8),w=rand(2,6),h=rand(3,9),V=l*w*h;if(L<=2)return numeric(`A rectangular prism has volume ${V} cubic inches and height ${h} inches. What is the area of its base?`,l*w,[V*h,V-h,l+w],[`Volume = base area × height.`,`Base area = ${V} ÷ ${h} = ${l*w} square inches.`],'Divide volume by height to find base area.');return numeric(`A rectangular prism has volume ${V} cm³, length ${l} cm, and height ${h} cm. What is its width?`,w,[V/l,V/h,l+h],[`Use V = length × width × height.`,`Width = ${V} ÷ (${l} × ${h}) = ${w} cm.`],'Divide by the product of the known dimensions.')});
add('consecutive','Consecutive integer word problems',[36],L=>{const step=L>=3?2:1,n=L>=4?3:2,start=step===2?2*rand(2,15)+1:rand(5,25),values=Array.from({length:n},(_,i)=>start+i*step),total=values.reduce((a,b)=>a+b,0),ans=values.join(', ');return question(`Find ${n} consecutive ${step===2?'odd ':''}integers whose sum is ${total}.`,ans,[values.map(x=>x+1).join(', '),values.map(x=>x-2).join(', '),values.map((x,i)=>start+i*(step===2?1:2)).join(', ')],[`Let the first integer be x. The others are ${values.slice(1).map((_,i)=>'x + '+(i+1)*step).join(' and ')}.`,`Their sum is ${n}x + ${step*n*(n-1)/2} = ${total}.`,`Solve: x = ${start}. The integers are ${ans}.`],'Consecutive integers differ by 1; consecutive odd integers differ by 2.')});
add('expressions','Translate words into expressions',[37,39],L=>{const n=rand(3,12),m=rand(2,6);if(L<=2)return question(`Which expression means “${n} less than x”?`,`x − ${n}`,[`${n} − x`,`x + ${n}`,`${n}x`],[`“Less than” means subtract from the quantity that follows.`,`Start with x, then subtract ${n}: x − ${n}.`],'Pay attention to the order in “less than.”');return question(`Which expression means “${m} times the sum of x and ${n}”${L>=4?', decreased by '+m:''}?`,`${m}(x + ${n})${L>=4?' − '+m:''}`,[`${m}x + ${n}${L>=4?' − '+m:''}`,`${m}(x − ${n})`,`${m}x + ${n+m}`],[`The sum is x + ${n}.`,`Multiply the entire sum by ${m}: ${m}(x + ${n}).`,L>=4?`Then subtract ${m}: ${m}(x + ${n}) − ${m}.`:'The parentheses keep the sum together.'],'Write the grouped sum first, then apply the other operations.')});
add('cross','Cross multiplication & rational equations',[38],L=>{const x=rand(2,8),b=rand(2,6),d=rand(2,5);if(L<=2)return numeric(`Solve x/${b} = ${x*d}/${b*d}.`,x,[x*d,x/b,b*x],[`Cross multiply: ${b*d}x = ${b*x*d}.`,`Divide by ${b*d}: x = ${x}.`],'Cross products are equal for a proportion.','',v=>'x = '+num(v));if(L===3){const off=rand(1,5);return numeric(`Solve (x + ${off})/${b} = ${x+off}/${b}.`,x,[x+off,x-off,b*(x+off)],[`Multiply both sides by ${b}: x + ${off} = ${x+off}.`,`Subtract ${off}: x = ${x}.`],'Multiply both sides by the denominator.','',v=>'x = '+num(v))}return question(`Solve 2/(x + 1) = (x + 2)/${pick([3])}. Select the complete solution set.`, 'x = 1 or x = −4',['x = 1 only','x = −4 only','x = 2 or x = −3'],['x ≠ −1 because the denominator cannot be zero.','Cross multiply: 6 = (x + 1)(x + 2).','Expand and rearrange: x² + 3x − 4 = 0.','Factor: (x + 4)(x − 1) = 0. Both −4 and 1 are allowed.'],'Cross multiply, expand, and solve the resulting quadratic.')});
add('scale','Scale drawings & similar rectangles',[24],L=>{const w=rand(3,8),h=rand(2,6),factor=rand(2,5);return numeric(`A rectangle is ${w} cm wide and ${h} cm tall. A similar rectangle is ${h*factor} cm tall. ${L>=4?'What is the area of the larger rectangle?':'How wide is the larger rectangle?'}`,L>=4?w*h*factor**2:w*factor,[w+factor,w*factor,w*h*factor,w*h*factor**2,w*factor+1],[`Scale factor = ${h*factor} ÷ ${h} = ${factor}.`,`New width = ${w} × ${factor} = ${w*factor} cm.`,L>=4?`Area = ${w*factor} × ${h*factor} = ${w*h*factor**2} cm².`:`The width is ${w*factor} cm.`],'Similar figures have the same scale factor for every length.')});
add('charts','Read charts & data tables',[39],L=>{const labels=['Blueberry','Grape','Peach','Strawberry'],v=shuffle([10,20,30,40]),target=v.indexOf(Math.max(...v)),chart=`<svg viewBox="0 0 420 250" role="img" aria-label="Bar chart of jars sold: ${labels.map((s,i)=>s+' '+v[i]).join(', ')}"><path fill="none" d="M40 25V190H410" stroke="#061746"/>${[0,10,20,30,40].map(n=>`<text x="30" y="${194-n*4}" text-anchor="end" font-size="13">${n}</text><path fill="none" d="M40 ${190-n*4}H410" stroke="#dce2ee"/>`).join('')}${v.map((n,i)=>`<rect x="${58+i*88}" y="${190-n*4}" width="52" height="${n*4}" fill="${i%2?'#cb1022':'#061746'}"/><text x="${84+i*88}" y="215" text-anchor="middle" font-size="12">${labels[i]}</text>`).join('')}</svg>`;if(L<=2)return question('Which flavor had the most jars sold?',labels[target],labels.filter((_,i)=>i!==target),[`Compare the heights of the bars.`,`${labels[target]} is tallest, with ${v[target]} jars sold.`],'Read the tallest bar.',chart);return numeric(`How many more jars of ${labels[target]} were sold than ${labels[v.indexOf(10)]}?`,30,[40,10,50],[`The bars show 40 and 10 jars.`,`Difference = 40 − 10 = 30 jars.`],'Subtract the smaller count from the larger.',chart)});
add('sets','Unions & intersections of sets',[41],L=>{const base=rand(1,8),A=[base,base+2,base+4,base+6],B=[base+2,base+3,base+4],C=[base+4,base+5,base+6],inter=A.filter(x=>B.includes(x)),union=[...new Set([...A,...B])].sort((a,b)=>a-b),ans=L<=2?inter: L===3?union:A.filter(x=>B.includes(x)||C.includes(x)),fmt=a=>'{'+a.join(', ')+'}';return question(`Let A = ${fmt(A)}, B = ${fmt(B)}${L>=4?', and C = '+fmt(C):''}. Find ${L<=2?'A ∩ B':L===3?'A ∪ B':'A ∩ (B ∪ C)'}.`,fmt(ans),[fmt(A),fmt(B),fmt(L<=2?union:inter),fmt([base+3])],[L<=2?'Intersection contains elements in both sets.':L===3?'Union contains all elements in either set, without duplicates.':'First combine B and C, then keep only elements also in A.',`The resulting set is ${fmt(ans)}.`],'∩ means “in both”; ∪ means “in either.”')});
add('transform','Coordinate reflections & rotations',[41],L=>{const x=rand(1,4),y=rand(-4,-1),rot=L>=3;const ans=rot?[-x,y]:[x,-y];return question(rot?`Point P is (${x}, ${y}). Rotate it 180° about the origin, then reflect it across the x-axis. Where does it end up?`:`Point P is (${x}, ${y}). Reflect it across the x-axis. What are its new coordinates?`,`(${ans[0]}, ${ans[1]})`,[`(${-x}, ${-y})`,`(${x}, ${y})`,`(${y}, ${x})`,`(${-x}, ${y})`,`(${x+1}, ${y})`,`(${x}, ${y+1})`],rot?[`A 180° rotation changes (x, y) to (−x, −y): (${-x}, ${-y}).`,`Reflection across the x-axis changes the sign of y: (${-x}, ${y}).`]:[`Reflection across the x-axis keeps x and reverses y.`,`(${x}, ${y}) becomes (${x}, ${-y}).`],'A 180° rotation changes both signs; an x-axis reflection changes only y.',graph(1,0,{line:false,points:[[x,y,'P']],label:`Coordinate grid showing P at (${x}, ${y}).`}))});
