topics.find(t=>t.id==='cross').gen=L=>{const x=rand(1,7),a=rand(1,4),b=rand(a+1,a+4);if(L<=2)return numeric(`Solve x/${a} = ${x*b}/${a*b}.`,x,[x*b,x/a,a*x],[`Cross multiply: ${a*b}x = ${a*x*b}.`,`Divide by ${a*b}: x = ${x}.`],'Cross products are equal for a proportion.','',v=>'x = '+num(v));if(L===3)return numeric(`Solve (x + ${b})/${a} = ${x+b}/${a}.`,x,[x+b,x-b,a*(x+b)],[`Multiply both sides by ${a}: x + ${b} = ${x+b}.`,`Subtract ${b}: x = ${x}.`],'Multiply both sides by the denominator.','',v=>'x = '+num(v));const neg=-(a+b+x),product=(x+a)*(x+b),ans=`x = ${x} or x = ${neg}`;return question(`Solve ${x+b}/(x + ${a}) = (x + ${b})/${x+a}. Select the complete solution set.`,ans,[`x = ${x} only`,`x = ${neg} only`,`x = ${x+1} or x = ${neg-1}`],[`x ≠ ${-a}, because the denominator cannot be zero.`,`Cross multiply: ${product} = (x + ${a})(x + ${b}).`,`Expand and rearrange: x² + ${a+b}x ${sign(a*b-product)} = 0.`,`Factor: (x − ${x})(x + ${-neg}) = 0.`,`Both solutions, ${x} and ${neg}, have nonzero denominators.`],'Cross multiply, then factor the resulting quadratic.')};
topics.find(t=>t.id==='systemwords').gen=L=>{const a=rand(2,5),b=rand(6,9),x=rand(3,10),y=rand(3,10),n=x+y,revenue=a*x+b*y;if(L<=2)return question(`Student tickets cost $${a}; adult tickets cost $${b}. There are ${n} tickets sold for $${revenue}. Let s be student tickets and a be adult tickets. Which system models this?`,`s + a = ${n}; ${a}s + ${b}a = ${revenue}`,[`${a}s + ${b}a = ${n}; s + a = ${revenue}`,`s − a = ${n}; ${a}s + ${b}a = ${revenue}`,`s + a = ${n}; ${b}s + ${a}a = ${revenue}`],[`The ticket count gives s + a = ${n}.`,`The money collected gives ${a}s + ${b}a = ${revenue}.`],'Write one equation for the count and one for the cost.');if(L===3)return numeric(`Student tickets cost $${a}; adult tickets cost $${b}. A total of ${n} tickets brings in $${revenue}. How many adult tickets were sold?`,y,[x,n,y+1],[`Let s + a = ${n} and ${a}s + ${b}a = ${revenue}.`,`Substitute s = ${n} − a: ${a*n} + ${b-a}a = ${revenue}.`,`So a = (${revenue} − ${a*n}) ÷ ${b-a} = ${y}.`],'Express one ticket type using the total count.');return numeric(`Two sandwiches and one drink cost $${2*a+b}. One sandwich and two drinks cost $${a+2*b}. What is the price of ${L===4?'one sandwich':'one sandwich and one drink'}?`,L===4?a:a+b,[b,2*a+b,a+2*b,a+b,a+1],[`Let s be sandwich price and d be drink price: 2s + d = ${2*a+b}, s + 2d = ${a+2*b}.`,`Double the first and subtract the second: 3s = ${3*a}, so s = ${a}.`,`Then d = ${2*a+b} − 2(${a}) = ${b}.`,L===4?`One sandwich costs $${a}.`:`Together they cost $${a+b}.`],'Use elimination to find one price, then substitution for the other.','',v=>'$'+num(v))};
function systemGraph(b,c,above=true,below=true,strict=false){const X=v=>180+v*22,Y=v=>180-v*22;let poly=[[-6,-6],[6,-6],[6,6],[-6,6]];for(const fn of [p=>above?p[1]-p[0]-b:p[0]+b-p[1],p=>below?-p[0]+c-p[1]:p[1]+p[0]-c]){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],z=poly[(i+1)%poly.length],fa=fn(a),fz=fn(z);if(fa>=0)out.push(a);if((fa>=0)!==(fz>=0)){const t=fa/(fa-fz);out.push([a[0]+t*(z[0]-a[0]),a[1]+t*(z[1]-a[1])])}}poly=out}const fill=`<polygon points="${poly.map(p=>`${X(p[0])},${Y(p[1])}`).join(' ')}" fill="#b9cafa" fill-opacity="0.65"/>`;return graph(1,b,{line:false,label:`System graph: y = x ${sign(b)}, ${strict?'dashed':'solid'} boundary, solution ${above?'above':'below'}; y = −x ${sign(c)}, solid boundary, solution ${below?'below':'above'}. Only the common region is shaded.`,extra:fill+`<path fill="none" d="M48 ${Y(-6+b)}L312 ${Y(6+b)}" stroke="#cb1022" stroke-width="3" ${strict?'stroke-dasharray="7 5"':''}/><path fill="none" d="M48 ${Y(6+c)}L312 ${Y(-6+c)}" stroke="#061746" stroke-width="3"/>`})}
add('systemgraph','Match systems to shaded regions',[15,16],L=>{const b=rand(-3,0),c=rand(2,4),strict=L>=3;return question(`Which graph shades the solution to both y ${strict?'>':'≥'} x ${sign(b)} and y ≤ −x ${sign(c)}?`,systemGraph(b,c,true,true,strict),[systemGraph(b,c,false,true,strict),systemGraph(b,c,true,false,strict),systemGraph(b,c,false,false,strict)],[`The first inequality shades above y = x ${sign(b)} and uses a ${strict?'dashed':'solid'} boundary.`,`The second shades below y = −x ${sign(c)} and uses a solid boundary.`,`The solution is the overlapping region between the two lines.`],'Find the graph with the correct common region and boundary styles.')});
add('anglevisual','Vertical & complementary angles',[22,23],L=>{const angle=rand(25,65),vertical=L>=3,ans=vertical?angle:90-angle;return numeric(vertical?`Two straight lines intersect. One angle is ${angle}°. What is the angle directly opposite it?`:`A right angle is split into angles of ${angle}° and x°. What is x?`,ans,[180-angle,angle,90+angle,ans+1],[vertical?'Opposite (vertical) angles at an intersection are equal.':'Complementary angles add to 90°.',vertical?`The opposite angle is ${angle}°.`:`x = 90 − ${angle} = ${ans}°.`],'Decide whether the angles are opposite or form a right angle.')});
add('multicharts','Compare changes in a bar chart',[39],L=>{const labels=['Blueberry','Grape','Peach','Strawberry'],v=[10,15,10,20],diff=shuffle([5,10,15,20]),w=v.map((n,i)=>n+diff[i]),max=diff.indexOf(20),chart=`<svg viewBox="0 0 440 280" role="img" aria-label="Jars sold in Year 1 then Year 2: ${labels.map((s,i)=>s+' '+v[i]+' then '+w[i]).join('; ')}"><text x="40" y="22" font-size="14" fill="#061746">Navy: Year 1</text><text x="225" y="22" font-size="14" fill="#cb1022">Red: Year 2</text><path fill="none" d="M40 40V220H420" stroke="#061746"/>${[0,10,20,30,40].map(n=>`<text x="30" y="${224-n*4}" text-anchor="end" font-size="13">${n}</text><path fill="none" d="M40 ${220-n*4}H420" stroke="#dce2ee"/>`).join('')}${v.map((n,i)=>`<rect x="${55+i*90}" y="${220-n*4}" width="25" height="${n*4}" fill="#061746"/><rect x="${82+i*90}" y="${220-w[i]*4}" width="25" height="${w[i]*4}" fill="#cb1022"/><text x="${82+i*90}" y="247" text-anchor="middle" font-size="12">${labels[i]}</text><text x="${67+i*90}" y="${214-n*4}" text-anchor="middle" font-size="11">${n}</text><text x="${95+i*90}" y="${214-w[i]*4}" text-anchor="middle" font-size="11">${w[i]}</text>`).join('')}</svg>`;if(L<=3)return question('Which flavor had the greatest increase from Year 1 to Year 2?',labels[max],labels.filter((_,i)=>i!==max),labels.map((s,i)=>`${s}: ${w[i]} − ${v[i]} = ${diff[i]} more jars.`).concat(`The greatest increase is ${labels[max]}, with 20 more jars.`),'Subtract Year 1 from Year 2 for each flavor.',chart);return numeric(`What is the total increase in jars sold across all four flavors?`,50,[v.reduce((a,b)=>a+b,0),w.reduce((a,b)=>a+b,0),20],[`Individual increases: ${diff.join(', ')} jars.`,`Total increase = ${diff.join(' + ')} = 50 jars.`],'Add the differences, not the Year 2 counts.',chart)});
add('probabilitycases','Dice, spinners & impossible events',[33],L=>{const sides=rand(5,9),n=rand(2,sides-1),impossible=L===1&&Math.random()<.5,answer=impossible?0:(sides-n)/sides;return question(impossible?`A fair ${sides}-section spinner is numbered 1 through ${sides}. What is the probability of spinning ${sides+1}?`:`A fair ${sides}-section spinner is numbered 1 through ${sides}. What is the probability of spinning a number greater than ${n}?`,impossible?'0':frac(sides-n,sides),[frac(n,sides),frac(1,sides),frac(sides-n,sides+1),frac(sides-n,sides+2),'1'],impossible?[`The number ${sides+1} does not appear on the spinner.`,`There are zero favorable outcomes, so the probability is 0.`]:[`Favorable numbers: ${Array.from({length:sides-n},(_,i)=>n+i+1).join(', ')}.`,`There are ${sides-n} favorable outcomes out of ${sides}.`,`Probability = ${frac(sides-n,sides)}.`],'Count the favorable sections and divide by all equally likely sections.')});

function generate(id,L,slot=rand(0,3)){const topic=topics.find(t=>t.id===id)||pick(topics),q=topic.gen(L);q.topic=topic.id;q.name=topic.name;q.level=L;const correct=q.choices.find(c=>c.correct),wrong=shuffle(q.choices.filter(c=>!c.correct));wrong.splice(slot%4,0,correct);q.choices=wrong;q.signature=q.topic+'|'+q.prompt+'|'+q.visual;return q}
function seeded(id,L,seed,slot=0){const previous=random;let n=seed>>>0;random=()=>{n=(n+0x6D2B79F5)>>>0;let t=Math.imul(n^(n>>>15),n|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296};try{return generate(id,L,slot)}finally{random=previous}}
root.QAS={topics,generate,seeded,rand,pick,shuffle,frac,graph};
